/// Returns the largest power of two `z` such that 1 ≤ z ≤ n.
pub fn largest_power_of_two_le(n: i8) -> i8 {
    // Start from the smallest power of two.
    let mut z: i8 = 1;
    // Double z as long as doing so stays within [1, n].
    // Since n >= 1, n / 2 is well-defined and non-negative.
    while z <= n / 2 {
        z <<= 1;
    }
    z
}

/// If `n` is odd, returns (n - 1) / 2.
/// If `n` is even, finds the largest power of two `z` ≤ n and returns (n - z) / 2.
pub fn solve(n: i8) -> i8 {
    if n % 2 != 0 {
        // odd case
        (n - 1) / 2
    } else {
        // even case
        let z = largest_power_of_two_le(n);
        (n - z) / 2
    }
}

